77	static int64_t ai_watch_elapsed_ms(FAR const struct timespec *now,
78	                                   FAR const struct timespec *then)
79	{
80	  return (int64_t)(now->tv_sec - then->tv_sec) * 1000 +
81	         (now->tv_nsec - then->tv_nsec) / 1000000;
82	}
83	
84	static bool ai_watch_deadline_reached(FAR const struct timespec *now,
85	                                      FAR const struct timespec *deadline)
86	{
87	  return now->tv_sec > deadline->tv_sec ||
88	         (now->tv_sec == deadline->tv_sec &&
89	          now->tv_nsec >= deadline->tv_nsec);
90	}
91	
92	static void ai_watch_advance_deadline(FAR struct timespec *deadline,
93	                                      long delay_ms)
94	{
95	  deadline->tv_nsec += delay_ms * 1000000;
96	  deadline->tv_sec += deadline->tv_nsec / 1000000000;
97	  deadline->tv_nsec %= 1000000000;
98	}
