100	static int ai_watch_button_initialize(FAR struct ai_watch_s *watch)
101	{
102	  btn_buttonset_t sample;
103	  ssize_t nread;
104	  int ret;
105	
106	  watch->button_fd = open(AI_WATCH_BUTTON_DEVICE, O_RDONLY | O_NONBLOCK);
107	  if (watch->button_fd < 0)
108	    {
109	      int errcode = errno;
110	
111	      printf("ERROR: Failed to open %s: %d\n",
112	             AI_WATCH_BUTTON_DEVICE, errcode);
113	      return -errcode;
114	    }
115	
116	  ret = ioctl(watch->button_fd, BTNIOC_SUPPORTED,
117	              (unsigned long)((uintptr_t)&watch->supported_buttons));
118	  if (ret < 0)
119	    {
120	      int errcode = errno;
121	
122	      printf("ERROR: BTNIOC_SUPPORTED failed: %d\n", errcode);
123	      close(watch->button_fd);
124	      watch->button_fd = -1;
125	      return -errcode;
126	    }
127	
128	  nread = read(watch->button_fd, &sample, sizeof(sample));
129	  if (nread != sizeof(sample))
130	    {
131	      int errcode = nread < 0 ? errno : EIO;
132	
133	      printf("ERROR: Initial button read failed: %d\n", errcode);
134	      close(watch->button_fd);
135	      watch->button_fd = -1;
136	      return -errcode;
137	    }
138	
139	  clock_gettime(CLOCK_MONOTONIC, &watch->next_button_poll);
140	  watch->button_raw_since = watch->next_button_poll;
141	  watch->button_raw_pressed = (sample & AI_WATCH_BUTTON_KEY2) != 0;
142	  watch->button_armed = !watch->button_raw_pressed;
143	
144	  printf("Supported buttons: 0x%02lx\n",
145	         (unsigned long)watch->supported_buttons);
146	  printf("KEY2 button monitor started\n");
147	  return OK;
148	}
149	
150	static void ai_watch_button_update(FAR struct ai_watch_s *watch,
151	                                   FAR const struct timespec *now)
152	{
153	  btn_buttonset_t sample;
154	  bool pressed;
155	  ssize_t nread;
156	
157	  if (watch->button_fd < 0 ||
158	      !ai_watch_deadline_reached(now, &watch->next_button_poll))
159	    {
160	      return;
161	    }
162	
163	  watch->next_button_poll = *now;
164	  ai_watch_advance_deadline(&watch->next_button_poll,
165	                            AI_WATCH_BUTTON_POLL_MS);
166	
167	  nread = read(watch->button_fd, &sample, sizeof(sample));
168	  if (nread != sizeof(sample))
169	    {
170	      if (nread < 0 && errno != EAGAIN && errno != EINTR)
171	        {
172	          printf("ERROR: Button read failed: %d\n", errno);
173	        }
174	
175	      return;
176	    }
177	
178	  pressed = (sample & AI_WATCH_BUTTON_KEY2) != 0;
179	  if (pressed != watch->button_raw_pressed)
180	    {
181	      watch->button_raw_pressed = pressed;
182	      watch->button_raw_since = *now;
183	    }
184	
185	  if (pressed)
186	    {
187	      if (watch->button_armed)
188	        {
189	          watch->button_armed = false;
190	          watch->bt_state = !watch->bt_state;
191	          lv_label_set_text(watch->bt_label,
192	                            watch->bt_state ? "BT: ON" : "BT: OFF");
193	          printf("KEY2 pressed: BT %s\n",
194	                 watch->bt_state ? "ON" : "OFF");
195	        }
196	    }
197	  else if (ai_watch_elapsed_ms(now, &watch->button_raw_since) >=
198	           AI_WATCH_BUTTON_RELEASE_MS)
199	    {
200	      watch->button_armed = true;
201	    }
202	}
