204	static void ai_watch_time_update(FAR struct ai_watch_s *watch)
205	{
206	  char date[32];
207	  char time[16];
208	  struct timespec ts;
209	  struct tm tm;
210	
211	  if (clock_gettime(CLOCK_REALTIME, &ts) < 0 ||
212	      localtime_r(&ts.tv_sec, &tm) == NULL ||
213	      tm.tm_year + 1900 < AI_WATCH_RTC_MIN_YEAR)
214	    {
215	      if (!watch->rtc_warning_printed)
216	        {
217	          printf("RTC time is not set; waiting for time synchronization\n");
218	          watch->rtc_warning_printed = true;
219	        }
220	
221	      if (watch->rtc_valid)
222	        {
223	          lv_label_set_text(watch->time_label, "--:--:--");
224	          lv_label_set_text(watch->date_label, "Date not set");
225	          watch->rtc_valid = false;
226	        }
227	
228	      return;
229	    }
230	
231	  watch->rtc_valid = true;
232	  if (ts.tv_sec == watch->displayed_second)
233	    {
234	      return;
235	    }
236	
237	  watch->displayed_second = ts.tv_sec;
238	  strftime(time, sizeof(time), "%H:%M:%S", &tm);
239	  strftime(date, sizeof(date), "%Y-%m-%d", &tm);
240	  lv_label_set_text(watch->time_label, time);
241	  lv_label_set_text(watch->date_label, date);
242	}
