255	  lv_obj_align(title, LV_ALIGN_TOP_MID, 0, 55);
256	
257	  watch->time_label = lv_label_create(screen);
258	  lv_label_set_text(watch->time_label, "--:--:--");
259	  lv_obj_set_style_text_color(watch->time_label, lv_color_white(), 0);
260	  lv_obj_set_style_text_font(watch->time_label, &lv_font_montserrat_24, 0);
261	  lv_obj_align(watch->time_label, LV_ALIGN_CENTER, 0, -10);
262	
263	  watch->date_label = lv_label_create(screen);
264	  lv_label_set_text(watch->date_label, "Date not set");
265	  lv_obj_set_style_text_color(watch->date_label,
266	                              lv_color_make(180, 180, 180), 0);
267	  lv_obj_set_style_text_font(watch->date_label,
268	                             &lv_font_montserrat_16, 0);
269	  lv_obj_align_to(watch->date_label, watch->time_label,
270	                  LV_ALIGN_OUT_BOTTOM_MID, 0, 12);
271	
272	  watch->bt_label = lv_label_create(screen);
273	  lv_label_set_text(watch->bt_label, "BT: OFF");
274	  lv_obj_set_style_text_color(watch->bt_label,
275	                              lv_color_make(0, 191, 255), 0);
276	  lv_obj_set_style_text_font(watch->bt_label,
277	                             &lv_font_montserrat_20, 0);
278	  lv_obj_align(watch->bt_label, LV_ALIGN_BOTTOM_MID, 0, -55);
279	}
