285	int main(int argc, FAR char *argv[])
286	{
287	  lv_nuttx_result_t result;
288	  lv_nuttx_dsc_t info;
289	  struct ai_watch_s watch =
290	  {
291	    .button_fd = -1,
292	    .displayed_second = -1,
293	  };
294	
295	  printf("AI Watch version %s\n", AI_WATCH_VERSION);
296	  printf("ai_watch started\n");
297	
298	  if (lv_is_initialized())
299	    {
300	      printf("ERROR: LVGL is already initialized\n");
301	      return EXIT_FAILURE;
302	    }
303	
304	  lv_init();
305	  lv_nuttx_dsc_init(&info);
306	  info.fb_path = "/dev/lcd0";
307	  lv_nuttx_init(&info, &result);
308	
309	  if (result.disp == NULL)
310	    {
311	      printf("ERROR: LVGL initialization failed\n");
312	      lv_deinit();
313	      return EXIT_FAILURE;
314	    }
315	
316	  printf("LVGL initialized, display ready\n");
317	  ai_watch_create_ui(&watch);
318	  ai_watch_time_update(&watch);
319	  ai_watch_button_initialize(&watch);
320	  printf("UI created; entering main loop\n");
321	
322	  for (; ; )
323	    {
324	      struct timespec now;
325	      uint32_t idle;
326	
327	      clock_gettime(CLOCK_MONOTONIC, &now);
328	      ai_watch_button_update(&watch, &now);
329	      ai_watch_time_update(&watch);
330	
331	      idle = lv_timer_handler();
332	      if (idle == 0 || idle > AI_WATCH_BUTTON_POLL_MS)
333	        {
334	          idle = AI_WATCH_BUTTON_POLL_MS;
335	        }
336	
337	      usleep(idle * 1000);
338	    }
339	
340	  return EXIT_SUCCESS;
341	}
