/****************************************************************************
 * Private Functions - Touch Input
 ****************************************************************************/

static void ai_watch_touch_event_cb(lv_event_t *e)
{
  FAR struct ai_watch_s *watch = lv_event_get_user_data(e);
  FAR lv_indev_t *indev = lv_indev_get_act();
  lv_indev_data_t data;
  struct timespec now;

  if (indev == NULL)
    {
      return;
    }

  lv_indev_get_data(indev, &data);
  clock_gettime(CLOCK_MONOTONIC, &now);

  if (data.state == LV_INDEV_STATE_PRESSED)
    {
      if (!watch->touch_active)
        {
          /* Touch started */

          watch->touch_active = true;
          watch->touch_start_x = data.point.x;
          watch->touch_start_y = data.point.y;
          watch->touch_start_time = now;
        }
    }
  else if (watch->touch_active)
    {
      /* Touch ended - calculate swipe */

      int dx = data.point.x - watch->touch_start_x;
      int dy = data.point.y - watch->touch_start_y;
      int64_t elapsed_ms = ai_watch_elapsed_ms(&now, &watch->touch_start_time);

      watch->touch_active = false;

      if (elapsed_ms > AI_WATCH_SWIPE_TIMEOUT_MS)
        {
          return;
        }

      /* Check for swipe gestures */

      if (abs(dy) > AI_WATCH_SWIPE_THRESHOLD && abs(dy) > abs(dx))
        {
          if (dy < 0)
            {
              /* Swipe up - go to app list from home */

              if (watch->current_page == AI_WATCH_PAGE_HOME)
                {
                  ai_watch_navigate_to(watch, AI_WATCH_PAGE_APP_LIST);
                }
            }
          else
            {
              /* Swipe down - go back from app list/settings */

              if (watch->current_page == AI_WATCH_PAGE_APP_LIST ||
                  watch->current_page == AI_WATCH_PAGE_SETTINGS)
                {
                  ai_watch_navigate_to(watch, AI_WATCH_PAGE_HOME);
                }
            }
        }
      else if (abs(dx) > AI_WATCH_SWIPE_THRESHOLD && abs(dx) > abs(dy))
        {
          if (dx > 0)
            {
              /* Swipe right - go back */

              if (watch->current_page == AI_WATCH_PAGE_APP_LIST ||
                  watch->current_page == AI_WATCH_PAGE_SETTINGS)
                {
                  ai_watch_navigate_to(watch, AI_WATCH_PAGE_HOME);
                }
            }
        }
      else
        {
          /* Tap detected - navigate based on current page */

          if (watch->current_page == AI_WATCH_PAGE_HOME)
            {
              ai_watch_navigate_to(watch, AI_WATCH_PAGE_APP_LIST);
            }
        }
    }
}

