129	static int64_t ai_watch_elapsed_ms(FAR const struct timespec *now,
130	                                   FAR const struct timespec *then)
131	{
132	  return (int64_t)(now->tv_sec - then->tv_sec) * 1000 +
133	         (now->tv_nsec - then->tv_nsec) / 1000000;
134	}
135	
136	static bool ai_watch_deadline_reached(FAR const struct timespec *now,
137	                                      FAR const struct timespec *deadline)
138	{
139	  return now->tv_sec > deadline->tv_sec ||
140	         (now->tv_sec == deadline->tv_sec &&
141	          now->tv_nsec >= deadline->tv_nsec);
142	}
143	
144	static void ai_watch_advance_deadline(FAR struct timespec *deadline,
145	                                      long delay_ms)
146	{
147	  deadline->tv_nsec += delay_ms * 1000000;
148	  deadline->tv_sec += deadline->tv_nsec / 1000000000;
149	  deadline->tv_nsec %= 1000000000;
150	}
