172	      int errcode = errno;
173	
174	      printf("ERROR: BTNIOC_SUPPORTED failed: %d\n", errcode);
175	      close(watch->button_fd);
176	      watch->button_fd = -1;
177	      return -errcode;
178	    }
179	
180	  nread = read(watch->button_fd, &sample, sizeof(sample));
181	  if (nread != sizeof(sample))
182	    {
183	      int errcode = nread < 0 ? errno : EIO;
184	
185	      printf("ERROR: Initial button read failed: %d\n", errcode);
186	      close(watch->button_fd);
187	      watch->button_fd = -1;
188	      return -errcode;
189	    }
190	
191	  clock_gettime(CLOCK_MONOTONIC, &watch->next_button_poll);
192	  watch->button_raw_since = watch->next_button_poll;
193	  watch->button_raw_pressed = (sample & AI_WATCH_BUTTON_KEY2) != 0;
194	  watch->button_armed = !watch->button_raw_pressed;
195	
196	  printf("Supported buttons: 0x%02lx\n",
197	         (unsigned long)watch->supported_buttons);
198	  printf("KEY2 button monitor started\n");
199	  return OK;
200	}
