206	static void ai_watch_button_update(FAR struct ai_watch_s *watch,
207	                                   FAR const struct timespec *now)
208	{
209	  btn_buttonset_t sample;
210	  bool pressed;
211	  ssize_t nread;
212	
213	  if (watch->button_fd < 0 ||
214	      !ai_watch_deadline_reached(now, &watch->next_button_poll))
215	    {
216	      return;
217	    }
218	
219	  watch->next_button_poll = *now;
220	  ai_watch_advance_deadline(&watch->next_button_poll,
221	                            AI_WATCH_BUTTON_POLL_MS);
222	
223	  nread = read(watch->button_fd, &sample, sizeof(sample));
224	  if (nread != sizeof(sample))
225	    {
226	      if (nread < 0 && errno != EAGAIN && errno != EINTR)
227	        {
228	          printf("ERROR: Button read failed: %d\n", errno);
229	        }
230	
231	      return;
232	    }
233	
234	  pressed = (sample & AI_WATCH_BUTTON_KEY2) != 0;
235	  if (pressed != watch->button_raw_pressed)
236	    {
237	      watch->button_raw_pressed = pressed;
238	      watch->button_raw_since = *now;
239	    }
240	
241	  if (pressed)
242	    {
243	      if (watch->button_armed)
244	        {
245	          watch->button_armed = false;
246	
247	          /* KEY2 acts as back button */
248	
249	          if (watch->current_page == AI_WATCH_PAGE_HOME)
250	            {
251	              /* On home page, toggle BT for testing */
252	
253	              watch->bt_state = !watch->bt_state;
254	              lv_label_set_text(watch->bt_label,
255	                                watch->bt_state ? "BT: ON" : "BT: OFF");
256	              printf("KEY2 pressed: BT %s\n",
257	                     watch->bt_state ? "ON" : "OFF");
258	            }
259	          else
260	            {
261	              /* On other pages, go back to home */
262	
263	              ai_watch_navigate_to(watch, AI_WATCH_PAGE_HOME);
264	              printf("KEY2 pressed: Back to home\n");
265	            }
266	        }
267	    }
268	  else if (ai_watch_elapsed_ms(now, &watch->button_raw_since) >=
269	           AI_WATCH_BUTTON_RELEASE_MS)
270	    {
271	      watch->button_armed = true;
272	    }
273	}
