275	static void ai_watch_time_update(FAR struct ai_watch_s *watch)
276	{
277	  char date[32];
278	  char time[16];
279	  char about[128];
280	  struct timespec ts;
281	  struct tm tm;
282	
283	  if (clock_gettime(CLOCK_REALTIME, &ts) < 0 ||
284	      localtime_r(&ts.tv_sec, &tm) == NULL ||
285	      tm.tm_year + 1900 < AI_WATCH_RTC_MIN_YEAR)
286	    {
287	      if (!watch->rtc_warning_printed)
288	        {
289	          printf("RTC time is not set; waiting for time synchronization\n");
290	          watch->rtc_warning_printed = true;
291	        }
292	
293	      if (watch->rtc_valid)
294	        {
295	          lv_label_set_text(watch->time_label, "--:--:--");
296	          lv_label_set_text(watch->date_label, "Date not set");
297	          watch->rtc_valid = false;
298	
299	          /* Update about label */
300	
301	          snprintf(about, sizeof(about),
302	                   "AI Watch v" AI_WATCH_VERSION "\n"
303	                   "Board: SF32LB52\n"
304	                   "Touch: Active\n"
305	                   "RTC: Not set");
306	          lv_label_set_text(watch->about_label, about);
307	        }
308	
309	      return;
310	    }
311	
312	  watch->rtc_valid = true;
313	  if (ts.tv_sec == watch->displayed_second)
314	    {
315	      return;
316	    }
317	
318	  watch->displayed_second = ts.tv_sec;
319	  strftime(time, sizeof(time), "%H:%M:%S", &tm);
320	  strftime(date, sizeof(date), "%Y-%m-%d", &tm);
321	  lv_label_set_text(watch->time_label, time);
322	  lv_label_set_text(watch->date_label, date);
323	
324	  /* Update about label with current time */
325	
326	  snprintf(about, sizeof(about),
327	           "AI Watch v" AI_WATCH_VERSION "\n"
328	           "Board: SF32LB52\n"
329	           "Touch: Active\n"
330	           "RTC: %s", time);
331	  lv_label_set_text(watch->about_label, about);
332	}
