679	/****************************************************************************
680	 * Private Functions - Touch Input (Coordinate-based)
681	 ****************************************************************************/
682	
683	static void ai_watch_touch_update(FAR struct ai_watch_s *watch)
684	{
685	  FAR lv_indev_t *indev = lv_indev_get_next(NULL);
686	  lv_indev_state_t state;
687	  lv_point_t point;
688	  struct timespec now;
689	
690	  if (indev == NULL)
691	    {
692	      return;
693	    }
694	
695	  state = lv_indev_get_state(indev);
696	  lv_indev_get_point(indev, &point);
697	  clock_gettime(CLOCK_MONOTONIC, &now);
698	
699	  if (state == LV_INDEV_STATE_PRESSED)
700	    {
701	      if (!watch->touch_active)
702	        {
703	          /* Touch started */
704	
705	          watch->touch_active = true;
706	          watch->touch_start_x = point.x;
707	          watch->touch_start_y = point.y;
708	          watch->touch_start_time = now;
709	        }
710	    }
711	  else if (watch->touch_active)
712	    {
713	      /* Touch ended - calculate swipe */
714	
715	      int dx = point.x - watch->touch_start_x;
716	      int dy = point.y - watch->touch_start_y;
717	      int64_t elapsed_ms = ai_watch_elapsed_ms(&now, &watch->touch_start_time);
718	
719	      watch->touch_active = false;
720	
721	      if (elapsed_ms > AI_WATCH_SWIPE_TIMEOUT_MS)
722	        {
723	          return;
724	        }
725	
726	      /* Check for swipe gestures */
727	
728	      if (abs(dy) > AI_WATCH_SWIPE_THRESHOLD && abs(dy) > abs(dx))
729	        {
730	          if (dy < 0)
731	            {
732	              /* Swipe up - go to app list from home */
733	
734	              if (watch->current_page == AI_WATCH_PAGE_HOME)
735	                {
736	                  ai_watch_navigate_to(watch, AI_WATCH_PAGE_APP_LIST);
737	                }
738	            }
739	          else
740	            {
741	              /* Swipe down - go back from app list/settings */
742	
743	              if (watch->current_page == AI_WATCH_PAGE_APP_LIST ||
744	                  watch->current_page == AI_WATCH_PAGE_SETTINGS)
745	                {
746	                  ai_watch_navigate_to(watch, AI_WATCH_PAGE_HOME);
747	                }
748	            }
749	        }
750	      else if (abs(dx) > AI_WATCH_SWIPE_THRESHOLD && abs(dx) > abs(dy))
751	        {
752	          if (dx > 0)
753	            {
754	              /* Swipe right - go back */
755	
756	              if (watch->current_page == AI_WATCH_PAGE_APP_LIST ||
757	                  watch->current_page == AI_WATCH_PAGE_SETTINGS)
758	                {
759	                  ai_watch_navigate_to(watch, AI_WATCH_PAGE_HOME);
760	                }
761	            }
762	        }
763	      else if (abs(dx) < AI_WATCH_SWIPE_THRESHOLD &&
764	               abs(dy) < AI_WATCH_SWIPE_THRESHOLD)
765	        {
766	          /* Tap detected - navigate based on current page */
767	
768	          if (watch->current_page == AI_WATCH_PAGE_HOME)
769	            {
770	              ai_watch_navigate_to(watch, AI_WATCH_PAGE_APP_LIST);
771	            }
772	        }
773	    }
774	}
775	
776	/****************************************************************************
777	 * Public Functions
778	 ****************************************************************************/
779	
780	int main(int argc, FAR char *argv[])
781	{
782	  lv_nuttx_result_t result;
783	  lv_nuttx_dsc_t info;
784	  struct ai_watch_s watch =
785	  {
786	    .button_fd = -1,
787	    .displayed_second = -1,
788	    .current_page = AI_WATCH_PAGE_HOME,
789	    .settings_brightness = 80,
790	    .settings_bt_enabled = false,
791	  };
792	
793	  printf("AI Watch version %s\n", AI_WATCH_VERSION);
794	  printf("ai_watch started\n");
795	
796	  if (lv_is_initialized())
797	    {
798	      printf("ERROR: LVGL is already initialized\n");
799	      return EXIT_FAILURE;
800	    }
801	
802	  lv_init();
803	  lv_nuttx_dsc_init(&info);
804	
805	  /* Configure display and touch input */
806	
807	  info.fb_path = "/dev/lcd0";
808	  info.input_path = AI_WATCH_INPUT_DEVICE;
809	
810	  lv_nuttx_init(&info, &result);
811	
812	  if (result.disp == NULL)
813	    {
814	      printf("ERROR: LVGL initialization failed\n");
815	      lv_deinit();
816	      return EXIT_FAILURE;
817	    }
818	
819	  printf("LVGL initialized, display ready\n");
820	
821	  if (result.indev != NULL)
822	    {
823	      printf("Touch input initialized: %s\n", AI_WATCH_INPUT_DEVICE);
824	    }
825	  else
826	    {
827	      printf("WARNING: Touch input not available\n");
828	    }
829	
830	  ai_watch_create_ui(&watch);
831	  ai_watch_time_update(&watch);
832	  ai_watch_button_initialize(&watch);
833	
834	  printf("UI created; entering main loop\n");
835	
836	  for (; ; )
837	    {
838	      struct timespec now;
839	      uint32_t idle;
840	
841	      clock_gettime(CLOCK_MONOTONIC, &now);
842	      ai_watch_button_update(&watch, &now);
843	      ai_watch_touch_update(&watch);
844	      ai_watch_time_update(&watch);
845	
846	      idle = lv_timer_handler();
847	      if (idle == 0 || idle > AI_WATCH_BUTTON_POLL_MS)
848	        {
849	          idle = AI_WATCH_BUTTON_POLL_MS;
850	        }
851	
852	      usleep(idle * 1000);
853	    }
854	
855	  return EXIT_SUCCESS;
856	}
